measures.expression:
CALCULATE (
    COUNTROWS (
        DISTINCT (
            UNION (
                SELECTCOLUMNS('Fact Kaimahi Course Progress', "KaimahiKey", 'Fact Kaimahi Course Progress'[Dim Kaimahi KEY]),
                SELECTCOLUMNS('Fact Kaimahi Certification Progress', "KaimahiKey", 'Fact Kaimahi Certification Progress'[Dim Kaimahi KEY])
            )
        )
    )
)
